'use strict';

// A detached flight still settles its original callers. The registry tracks
// only flights available for subsequent readers of each key.
function createFlights() {
  const pending = new Map();

  return {
    run(key, work, commit) {
      if (pending.has(key)) return pending.get(key);
      // Only the currently registered flight may remove itself or commit.
      // A detached (obsolete) flight still settles its own waiters but must
      // neither store its value nor detach a newer flight for the key.
      const promise = Promise.resolve().then(work).then(
        value => {
          if (pending.get(key) === promise) {
            pending.delete(key);
            commit(value);
          }
          return value;
        },
        reason => {
          if (pending.get(key) === promise) pending.delete(key);
          throw reason;
        }
      );
      pending.set(key, promise);
      return promise;
    },
    forget(key) {
      pending.delete(key);
    },
    clear() {
      pending.clear();
    }
  };
}

module.exports = { createFlights };

