'use strict';
const assert = require('node:assert/strict');
const { createCache } = require('./src/cache');
const tick = () => new Promise(r => setImmediate(r));
const deferred = () => { let resolve, reject; const promise = new Promise((res, rej) => { resolve = res; reject = rej; }); return { promise, resolve, reject }; };

(async () => {
  // 1. Stale flight settles AFTER a fresh flight already committed: must not overwrite.
  {
    let now = 0; const gate = deferred(); let calls = 0;
    const c = createCache({ now: () => now, ttlMs: 100, load() { calls++; return calls === 1 ? gate.promise : 'v' + calls; } });
    const old = c.get('k'); await tick();
    c.invalidate('k');
    const fresh = await c.get('k');
    assert.equal(fresh, 'v2');
    gate.resolve('stale');
    assert.equal(await old, 'stale');            // original waiter still gets own value
    assert.equal(await c.get('k'), 'v2');        // stale commit must not resurrect
    assert.equal(calls, 2);
  }
  // 2. Old flight settling must not detach the newer registered flight (dedup intact).
  {
    const a = deferred(); const b = deferred(); let calls = 0;
    const c = createCache({ now: () => 0, ttlMs: 100, load() { calls++; return calls === 1 ? a.promise : b.promise; } });
    const r1 = c.get('k'); await tick();
    c.invalidate('k');
    const r2 = c.get('k'); await tick();
    const r3 = c.get('k');                       // must join flight b
    a.resolve('old'); await tick();              // old settles first while b pending
    assert.equal(calls, 2);
    b.resolve('new');
    assert.equal(await r1, 'old');
    assert.equal(await r2, 'new');
    assert.equal(await r3, 'new');
    assert.equal(calls, 2);                      // r3 joined, no third load
  }
  // 3. Rejected load: not cached, all waiters same reason, subsequent get retries.
  {
    let calls = 0; const reason = Symbol('nope');
    const c = createCache({ now: () => 0, ttlMs: 100, load() { calls++; return calls === 1 ? Promise.reject(reason) : 'ok'; } });
    const [e1, e2] = await Promise.all([c.get('k'), c.get('k')].map(p => p.catch(e => e)));
    assert.equal(e1, reason); assert.equal(e2, reason);
    assert.equal(await c.get('k'), 'ok');        // retry happened
    assert.equal(calls, 2);
  }
  // 4. Synchronous throw in load: same rules.
  {
    let calls = 0;
    const c = createCache({ now: () => 0, load() { calls++; if (calls === 1) throw 'boom'; return 'ok'; } });
    await assert.rejects(c.get('k'), e => e === 'boom');
    assert.equal(await c.get('k'), 'ok');
  }
  // 5. set() wins over a later completion of the detached load; expiry of set value starts a NEW load.
  {
    let now = 0; const g = deferred(); let calls = 0;
    const c = createCache({ now: () => now, ttlMs: 100, load() { calls++; return calls === 1 ? g.promise : 'v' + calls; } });
    const r1 = c.get('k'); await tick();
    c.set('k', 'manual');
    g.resolve('stale');
    assert.equal(await r1, 'stale');
    assert.equal(await c.get('k'), 'manual');    // old completion must not overwrite set value
    now = 200;                                   // set value expired while... old already settled
    assert.equal(await c.get('k'), 'v2');        // new load, not the detached one
    assert.equal(calls, 2);
  }
  // 6. set() value expires WHILE an old detached load still pending: new load, not detached one.
  {
    let now = 0; const g = deferred(); let calls = 0;
    const c = createCache({ now: () => now, ttlMs: 100, load() { calls++; return calls === 1 ? g.promise : 'v' + calls; } });
    const r1 = c.get('k'); await tick();
    c.set('k', 'manual');
    now = 200;
    const r2 = c.get('k'); await tick();         // triggers load #2
    g.resolve('stale');                          // old load completes after
    assert.equal(await r1, 'stale');
    assert.equal(await r2, 'v2');
    assert.equal(await c.get('k'), 'v2');
    assert.equal(calls, 2);
  }
  // 7. load synchronously invalidating its own key before returning: its value must not be stored.
  {
    let calls = 0; let c;
    c = createCache({ now: () => 0, ttlMs: 100, load(k) { calls++; if (calls === 1) c.invalidate(k); return 'v' + calls; } });
    assert.equal(await c.get('k'), 'v1');        // waiter still gets the value
    assert.equal(await c.get('k'), 'v2');        // but nothing cached
    assert.equal(calls, 2);
  }
  // 8. load synchronously set()s its own key: set value wins over the load result.
  {
    let calls = 0; let c;
    c = createCache({ now: () => 0, ttlMs: 100, load(k) { calls++; if (calls === 1) c.set(k, 'manual'); return 'loaded'; } });
    assert.equal(await c.get('k'), 'loaded');
    assert.equal(await c.get('k'), 'manual');
    assert.equal(calls, 1);
  }
  // 9. clear() barrier + dedup of concurrent reads + ttlMs=0 dedupes unsettled only.
  {
    let calls = 0; const g = deferred();
    const c = createCache({ now: () => 0, ttlMs: 0, load() { calls++; return calls === 1 ? g.promise : 'v' + calls; } });
    const p1 = c.get('k'); const p2 = c.get('k');
    g.resolve('x');
    assert.equal(await p1, 'x'); assert.equal(await p2, 'x');
    assert.equal(calls, 1);                      // deduped while unsettled
    assert.equal(await c.get('k'), 'v2');        // settled value never reused at ttl 0
    c.clear();
    assert.equal(c.size, 0);
    assert.equal(await c.get('k'), 'v3');
  }
  // 10. size counts unexpired values only; reading size does not detach flights.
  {
    let now = 0; const g = deferred();
    const c = createCache({ now: () => now, ttlMs: 100, load: () => g.promise });
    const p = c.get('k');
    c.set('e', 1);
    assert.equal(c.size, 1);
    now = 200;
    assert.equal(c.size, 0);
    g.resolve('done');
    assert.equal(await p, 'done');               // flight still alive after size reads
    assert.equal(await c.get('k'), 'done');      // committed at now=200, ttl fresh
  }
  console.log('all scratch checks passed');
})().catch(e => { console.error(e); process.exit(1); });

